import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1400;
const CX = W / 2;

const COLORS = {
  forward: { fill: '#e8f5e9', stroke: '#2e7d32' },
  backward: { fill: '#ffebee', stroke: '#c62828' },
  weight: { fill: '#e3f2fd', stroke: '#1565c0' },
  loss: { fill: '#fff3e0', stroke: '#e65100' },
  memory: { fill: '#fff8e1', stroke: '#f9a825' },
  update: { fill: '#f3e5f5', stroke: '#6a1b9a' },
  text: { fill: '#e3f2fd', stroke: '#1976d2' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 100;
const STEP_GAP = 560;
const BOX_TO_ROW = 320;
const ARROW_MARGIN = 36;
const FOOTER_PAD = 70;

interface BackpropStep extends StepInfo {}
type BackpropVariant = 'computation_graph' | 'chain_rule' | 'memory_analysis';

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowH(
  g: Gsel, xFrom: number, xTo: number, y: number, color = '#94a3b8', margin = ARROW_MARGIN
): void {
  const dir = xTo >= xFrom ? 1 : -1;
  drawArrow(g as Sel, xFrom + dir * margin, y, xTo - dir * margin, y, { color });
}

function arrowDown(
  g: Gsel, x: number, yFrom: number, yTo: number, color = '#94a3b8'
): void {
  drawArrow(g as Sel, x, yFrom + ARROW_MARGIN, x, yTo - ARROW_MARGIN, { color });
}

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = W - 120
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 32).attr('cy', y + BOX_H / 2)
    .attr('r', 18).attr('fill', stroke);
  lbl(g, cx - w / 2 + 32, y + BOX_H / 2 + 1, String(sn), { size: 15, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 62, y + BOX_H / 2 - 10, title, { size: 16, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 62, y + BOX_H / 2 + 14, formula, { size: 11, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(420, text.length * 7.2 + 40);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 15).attr('width', w).attr('height', 30)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1);
  lbl(g, cx, cy + 1, text, { size: 11, color, font: 'monospace' });
}

function sampleNote(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(260, text.length * 6.5 + 32);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 13).attr('width', w).attr('height', 26)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 10, color, font: 'monospace' });
}

function drawTensorBox(
  g: Gsel, cx: number, cy: number, label: string, sublabel: string,
  w: number, h: number, fill: string, stroke: string
): void {
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 2);
  lbl(g, cx, cy - 4, label, { size: 14, weight: '600', color: stroke });
  lbl(g, cx, cy + 14, sublabel, { size: 10, color: COLORS.muted, font: 'monospace' });
}

function drawOpNode(
  g: Gsel, cx: number, cy: number, label: string, stroke: string, r = 30
): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', r)
    .attr('fill', '#fff').attr('stroke', stroke).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, label, { size: 12, weight: '600', color: stroke });
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): BackpropStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function renderComputationGraph(
  g: Gsel, startY: number, seqLen: number, dModel: number, numClasses: number
): { steps: BackpropStep[]; y: number } {
  const steps: BackpropStep[] = [];
  let y = startY;

  // Step 1: Input & Parameters
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input & Parameters',
      `x: [${seqLen}×${dModel}], W1: [${dModel}×${dModel}], W2: [${dModel}×${numClasses}]`,
      COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xPos = [CX - 400, CX, CX + 400];
    drawTensorBox(gs, xPos[0], rowY, 'x', `[${seqLen}×${dModel}]`, 160, 70,
      COLORS.weight.fill, COLORS.weight.stroke);
    drawTensorBox(gs, xPos[1], rowY, 'W1', `[${dModel}×${dModel}]`, 160, 70,
      COLORS.weight.fill, COLORS.weight.stroke);
    drawTensorBox(gs, xPos[2], rowY, 'W2', `[${dModel}×${numClasses}]`, 160, 70,
      COLORS.weight.fill, COLORS.weight.stroke);

    shapeEq(gs, CX, rowY + 80,
      `input x, weights W1, W2 initialized randomly`, COLORS.text.stroke);
    sampleNote(gs, CX, rowY + 80 + 38,
      `total params: ${dModel * dModel + dModel * numClasses}`, COLORS.text.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Input', 'Input & Parameters',
      'x, W1, W2',
      'The forward pass begins with input tensor x and weight matrices W1, W2. All parameters are initialized randomly (e.g., Xavier or Kaiming initialization).',
      'step-input', COLORS.text.stroke, COLORS.text.fill,
      [`x = torch.randn(${seqLen}, ${dModel})`, `W1 = torch.randn(${dModel}, ${dModel})`, `W2 = torch.randn(${dModel}, ${numClasses})`]));
  }

  // Step 2: Forward Pass — Two-row layout
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-forward', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Forward Pass',
      'h = x·W1, a = σ(h), y = a·W2, p = softmax(y), L = CE(p, target)',
      COLORS.forward.fill, COLORS.forward.stroke);
    const row1Y = hBottom + BOX_TO_ROW;
    const row2Y = row1Y + 180;

    // Row 1: x → ×W1 → h → σ → a
    const r1 = [
      { label: 'x', sub: 'input', x: CX - 500, fill: COLORS.weight.fill, stroke: COLORS.weight.stroke },
      { label: '×W1', op: true, x: CX - 340, fill: '#fff', stroke: COLORS.weight.stroke },
      { label: 'h', sub: `[${seqLen}×${dModel}]`, x: CX - 180, fill: COLORS.forward.fill, stroke: COLORS.forward.stroke },
      { label: 'σ', op: true, x: CX - 20, fill: '#fff', stroke: COLORS.forward.stroke },
      { label: 'a', sub: `[${seqLen}×${dModel}]`, x: CX + 140, fill: COLORS.forward.fill, stroke: COLORS.forward.stroke },
    ];

    for (const node of r1) {
      if (node.op) {
        drawOpNode(gs, node.x, row1Y, node.label, node.stroke, 28);
      } else {
        drawTensorBox(gs, node.x, row1Y, node.label, node.sub!, 100, 60, node.fill, node.stroke);
      }
    }

    for (let i = 0; i < r1.length - 1; i++) {
      const x1 = r1[i].x + (r1[i].op ? 28 : 50);
      const x2 = r1[i + 1].x - (r1[i + 1].op ? 28 : 50);
      if (x2 - x1 > ARROW_MARGIN * 2) {
        drawArrow(gs as Sel, x1, row1Y, x2, row1Y, { color: COLORS.forward.stroke });
      }
    }

    // Connecting arrow from a (row 1) down to row 2
    arrowDown(gs, CX + 140, row1Y + 30, row2Y - 30, COLORS.forward.stroke);

    // Row 2: a → ×W2 → y → sfm → p → CE → L
    const r2 = [
      { label: 'a', sub: `[${seqLen}×${dModel}]`, x: CX - 500, fill: COLORS.forward.fill, stroke: COLORS.forward.stroke },
      { label: '×W2', op: true, x: CX - 340, fill: '#fff', stroke: COLORS.weight.stroke },
      { label: 'y', sub: `[${seqLen}×${numClasses}]`, x: CX - 180, fill: COLORS.forward.fill, stroke: COLORS.forward.stroke },
      { label: 'sfm', op: true, x: CX - 20, fill: '#fff', stroke: COLORS.loss.stroke },
      { label: 'p', sub: `[${seqLen}×${numClasses}]`, x: CX + 140, fill: COLORS.loss.fill, stroke: COLORS.loss.stroke },
      { label: 'CE', op: true, x: CX + 300, fill: '#fff', stroke: '#d32f2f' },
      { label: 'L', sub: 'scalar', x: CX + 440, fill: '#ffebee', stroke: '#d32f2f' },
    ];

    for (const node of r2) {
      if (node.op) {
        drawOpNode(gs, node.x, row2Y, node.label, node.stroke, 28);
      } else {
        drawTensorBox(gs, node.x, row2Y, node.label, node.sub!, 100, 60, node.fill, node.stroke);
      }
    }

    for (let i = 0; i < r2.length - 1; i++) {
      const x1 = r2[i].x + (r2[i].op ? 28 : 50);
      const x2 = r2[i + 1].x - (r2[i + 1].op ? 28 : 50);
      if (x2 - x1 > ARROW_MARGIN * 2) {
        drawArrow(gs as Sel, x1, row2Y, x2, row2Y, { color: COLORS.forward.stroke });
      }
    }

    // Dimension annotations
    lbl(gs, CX - 340, row1Y + 50, 'matmul', { size: 9, color: COLORS.muted, font: 'monospace' });
    lbl(gs, CX - 20, row1Y + 50, 'activation', { size: 9, color: COLORS.muted, font: 'monospace' });
    lbl(gs, CX - 340, row2Y + 50, 'matmul', { size: 9, color: COLORS.muted, font: 'monospace' });
    lbl(gs, CX - 20, row2Y + 50, 'softmax', { size: 9, color: COLORS.muted, font: 'monospace' });
    lbl(gs, CX + 300, row2Y + 50, 'loss', { size: 9, color: COLORS.muted, font: 'monospace' });

    shapeEq(gs, CX, row2Y + 80,
      `h = x·W1 → a = σ(h) → y = a·W2 → p = softmax(y) → L = CE(p, target)`,
      COLORS.forward.stroke);
    sampleNote(gs, CX, row2Y + 80 + 38,
      `forward pass computes loss through 2 linear layers + activation + softmax`,
      COLORS.forward.stroke);

    y = row2Y + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Forward', 'Forward Pass',
      'h=x·W1, a=σ(h), y=a·W2, p=softmax(y), L=CE(p,tgt)',
      'The forward pass computes predictions and loss. Input x is transformed through two linear layers with activation in between, then softmax produces class probabilities, and cross-entropy measures prediction error.',
      'step-forward', COLORS.forward.stroke, COLORS.forward.fill,
      [`h = x @ W1`, `a = F.relu(h)`, `y = a @ W2`, `p = F.softmax(y, dim=-1)`, `L = F.cross_entropy(p, target)`]));
  }

  // Step 3: Loss & Softmax Gradient
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-loss-grad', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Loss & Softmax Gradient',
      '∂L/∂p = p - one_hot(target), ∂L/∂y = p - y_true (simplified)',
      COLORS.backward.fill, COLORS.backward.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xPos = [CX - 380, CX, CX + 380];
    drawTensorBox(gs, xPos[0], rowY, 'L', 'scalar loss', 120, 70,
      '#ffebee', '#d32f2f');
    drawTensorBox(gs, xPos[1], rowY, '∂L/∂p', `[${seqLen}×${numClasses}]`, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, xPos[2], rowY, '∂L/∂y', `[${seqLen}×${numClasses}]`, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);

    arrowH(gs, xPos[0], xPos[1], rowY, COLORS.backward.stroke);
    arrowH(gs, xPos[1], xPos[2], rowY, COLORS.backward.stroke);

    lbl(gs, (xPos[0] + xPos[1]) / 2, rowY - 60, '∂L/∂p = p - one_hot(tgt)',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });
    lbl(gs, (xPos[1] + xPos[2]) / 2, rowY - 60, '∂L/∂y = p - y_true (simplified)',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });

    shapeEq(gs, CX, rowY + 80,
      `softmax+CE simplifies: ∂L/∂y_i = p_i - (1 if i=target else 0)`,
      COLORS.backward.stroke);
    sampleNote(gs, CX, rowY + 80 + 38,
      `avoids explicit Jacobian computation — clean gradient signal`,
      COLORS.backward.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Loss Grad', 'Loss & Softmax Gradient',
      '∂L/∂p = p - y_true, ∂L/∂y = p - y_true',
      'The backward pass starts from the loss. The gradient through softmax+cross-entropy simplifies to p - one_hot(target), avoiding explicit Jacobian computation.',
      'step-loss-grad', COLORS.backward.stroke, COLORS.backward.fill,
      [`dL_dp = p - F.one_hot(target, ${numClasses})`, `# simplified: dL_dy = p - y_true`]));
  }

  // Step 4: Backward Pass — Chain Rule (two rows)
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-backward', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Backward Pass — Chain Rule',
      'dL/dW2 = a^T·∂L/∂y, dL/dh = (∂L/∂y·W2^T)⊙σ\'(h), dL/dW1 = x^T·dL/dh',
      COLORS.backward.fill, COLORS.backward.stroke);
    const row1Y = hBottom + BOX_TO_ROW;
    const row2Y = row1Y + 200;

    // Row 1: ∂L/∂y → ∂L/∂W2, ∂L/∂a → ∂L/∂h
    const r1 = [
      { label: '∂L/∂y', sub: `[${seqLen}×${numClasses}]`, x: CX - 480 },
      { label: '∂L/∂W2', sub: `[${dModel}×${numClasses}]`, x: CX - 160 },
      { label: '∂L/∂a', sub: `[${seqLen}×${dModel}]`, x: CX + 160 },
      { label: '∂L/∂h', sub: `[${seqLen}×${dModel}]`, x: CX + 480 },
    ];

    for (const grad of r1) {
      drawTensorBox(gs, grad.x, row1Y, grad.label, grad.sub, 150, 70,
        COLORS.backward.fill, COLORS.backward.stroke);
    }

    arrowH(gs, r1[0].x, r1[1].x, row1Y, COLORS.backward.stroke);
    arrowH(gs, r1[1].x, r1[2].x, row1Y, COLORS.backward.stroke);
    arrowH(gs, r1[2].x, r1[3].x, row1Y, COLORS.backward.stroke);

    // Formula labels above arrows
    lbl(gs, (r1[0].x + r1[1].x) / 2, row1Y - 60, '∂L/∂W2 = a^T · ∂L/∂y',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });
    lbl(gs, (r1[1].x + r1[2].x) / 2, row1Y - 60, '∂L/∂a = ∂L/∂y · W2^T',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });
    lbl(gs, (r1[2].x + r1[3].x) / 2, row1Y - 60, '∂L/∂h = ∂L/∂a ⊙ σ\'(h)',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });

    // Dimension alignment annotations
    lbl(gs, (r1[0].x + r1[1].x) / 2, row1Y + 55, `a^T: [${dModel}×${seqLen}] · ∂L/∂y: [${seqLen}×${numClasses}]`,
      { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'middle' });

    // Connecting arrow from ∂L/∂h down to row 2
    arrowDown(gs, CX + 480, row1Y + 35, row2Y - 35, COLORS.backward.stroke);

    // Row 2: ∂L/∂h → ∂L/∂W1, ∂L/∂x
    const r2 = [
      { label: '∂L/∂h', sub: `[${seqLen}×${dModel}]`, x: CX - 340 },
      { label: '∂L/∂W1', sub: `[${dModel}×${dModel}]`, x: CX },
      { label: '∂L/∂x', sub: `[${seqLen}×${dModel}]`, x: CX + 340 },
    ];

    for (const grad of r2) {
      drawTensorBox(gs, grad.x, row2Y, grad.label, grad.sub, 150, 70,
        COLORS.backward.fill, COLORS.backward.stroke);
    }

    arrowH(gs, r2[0].x, r2[1].x, row2Y, COLORS.backward.stroke);
    arrowH(gs, r2[1].x, r2[2].x, row2Y, COLORS.backward.stroke);

    lbl(gs, (r2[0].x + r2[1].x) / 2, row2Y - 60, '∂L/∂W1 = x^T · ∂L/∂h',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });
    lbl(gs, (r2[1].x + r2[2].x) / 2, row2Y - 60, '∂L/∂x = ∂L/∂h · W1^T',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });

    lbl(gs, (r2[0].x + r2[1].x) / 2, row2Y + 55, `x^T: [${dModel}×${seqLen}] · ∂L/∂h: [${seqLen}×${dModel}]`,
      { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'middle' });

    shapeEq(gs, CX, row2Y + 90,
      `chain rule propagates gradients backward through each operation`,
      COLORS.backward.stroke);
    sampleNote(gs, CX, row2Y + 90 + 38,
      `gradient flow: loss → softmax → W2 → activation → W1 → input`,
      COLORS.backward.stroke);

    y = row2Y + 90 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Backward', 'Backward Pass — Chain Rule',
      'dL/dW = dL/dy · dy/dh · dh/dW',
      'Backpropagation applies the chain rule to compute gradients for each parameter. Gradients flow backward through the computation graph, with each operation contributing its local derivative.',
      'step-backward', COLORS.backward.stroke, COLORS.backward.fill,
      [`dL_dW2 = a.T @ dL_dy`, `dL_da = dL_dy @ W2.T`, `dL_dh = dL_da * (h > 0).float()`, `dL_dW1 = x.T @ dL_dh`, `dL_dx = dL_dh @ W1.T`]));
  }

  // Step 5: Weight Update
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-update', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Weight Update',
      'W1_new = W1 - lr·∂L/∂W1, W2_new = W2 - lr·∂L/∂W2',
      COLORS.update.fill, COLORS.update.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xPos = [CX - 420, CX - 140, CX + 140, CX + 420];
    drawTensorBox(gs, xPos[0], rowY, 'W1', `[${dModel}×${dModel}]`, 150, 70,
      COLORS.weight.fill, COLORS.weight.stroke);
    drawTensorBox(gs, xPos[1], rowY, '∂L/∂W1', `[${dModel}×${dModel}]`, 150, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, xPos[2], rowY, 'W2', `[${dModel}×${numClasses}]`, 150, 70,
      COLORS.weight.fill, COLORS.weight.stroke);
    drawTensorBox(gs, xPos[3], rowY, '∂L/∂W2', `[${dModel}×${numClasses}]`, 150, 70,
      COLORS.backward.fill, COLORS.backward.stroke);

    // Arrows between pairs
    arrowH(gs, xPos[0], xPos[1], rowY, COLORS.update.stroke);
    arrowH(gs, xPos[2], xPos[3], rowY, COLORS.update.stroke);

    lbl(gs, (xPos[0] + xPos[1]) / 2, rowY - 60, 'W1 - lr·∂L/∂W1 → W1_new',
      { size: 11, color: COLORS.update.stroke, font: 'monospace', anchor: 'middle' });
    lbl(gs, (xPos[2] + xPos[3]) / 2, rowY - 60, 'W2 - lr·∂L/∂W2 → W2_new',
      { size: 11, color: COLORS.update.stroke, font: 'monospace', anchor: 'middle' });

    shapeEq(gs, CX, rowY + 90,
      `SGD: W = W - lr·∂L/∂W, lr = 0.001`,
      COLORS.update.stroke);
    sampleNote(gs, CX, rowY + 90 + 38,
      `weights updated in opposite direction of gradient to minimize loss`,
      COLORS.update.stroke);

    y = rowY + 90 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Update', 'Weight Update',
      'W = W - lr·∂L/∂W',
      'After computing gradients, parameters are updated using gradient descent. The learning rate controls step size. Each weight moves in the direction that reduces loss.',
      'step-update', COLORS.update.stroke, COLORS.update.fill,
      [`lr = 0.001`, `W1.data -= lr * W1.grad`, `W2.data -= lr * W2.grad`, `W1.grad.zero_()`, `W2.grad.zero_()`]));
  }

  return { steps, y };
}

function renderChainRule(
  g: Gsel, startY: number, seqLen: number, dModel: number, numClasses: number
): { steps: BackpropStep[]; y: number } {
  const steps: BackpropStep[] = [];
  let y = startY;

  // Step 1: Composite Function Definition
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-composite', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Composite Function',
      'L = f₅(f₄(f₃(f₂(f₁(x; W1)); W2)))',
      COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const layers = [
      { fn: 'f₁(x,W1) = x·W1', out: 'h', x: CX - 480 },
      { fn: 'f₂(h) = σ(h)', out: 'a', x: CX - 240 },
      { fn: 'f₃(a,W2) = a·W2', out: 'y', x: CX },
      { fn: 'f₄(y) = softmax(y)', out: 'p', x: CX + 240 },
      { fn: 'f₅(p) = CE(p,tgt)', out: 'L', x: CX + 480 },
    ];

    for (let i = 0; i < layers.length; i++) {
      const layer = layers[i];
      gs.append('rect').attr('x', layer.x - 90).attr('y', rowY - 35).attr('width', 180).attr('height', 70)
        .attr('rx', 6).attr('fill', '#fff').attr('stroke', COLORS.text.stroke).attr('stroke-width', 1.5);
      lbl(gs, layer.x, rowY - 10, layer.fn, { size: 11, color: COLORS.text.stroke, font: 'monospace' });
      lbl(gs, layer.x, rowY + 16, `→ ${layer.out}`, { size: 12, weight: '600', color: COLORS.text.stroke });

      if (i < layers.length - 1) {
        const x1 = layer.x + 90;
        const x2 = layers[i + 1].x - 90;
        drawArrow(gs as Sel, x1, rowY, x2, rowY, { color: COLORS.text.stroke });
      }
    }

    shapeEq(gs, CX, rowY + 80,
      `L = CE(softmax(σ(x·W1)·W2), target)`,
      COLORS.text.stroke);
    sampleNote(gs, CX, rowY + 80 + 38,
      `nested composition of 5 functions: 2 linear + activation + softmax + loss`,
      COLORS.text.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Composite', 'Composite Function Definition',
      'L = f₅(f₄(f₃(f₂(f₁))))',
      'The neural network computes a composition of functions. Each layer transforms its input, creating a nested structure where the final loss depends on all intermediate computations.',
      'step-composite', COLORS.text.stroke, COLORS.text.fill,
      [`h = x @ W1`, `a = F.relu(h)`, `y = a @ W2`, `p = F.softmax(y, dim=-1)`, `L = F.cross_entropy(p, target)`]));
  }

  // Step 2: Outer Derivative
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-outer', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Outer Derivative — dL/dp & dL/dy',
      '∂L/∂p = p - one_hot(target), ∂L/∂y = p - y_true (simplified)',
      COLORS.backward.fill, COLORS.backward.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xPos = [CX - 380, CX, CX + 380];
    drawTensorBox(gs, xPos[0], rowY, 'p', `[${seqLen}×${numClasses}]`, 160, 70,
      COLORS.loss.fill, COLORS.loss.stroke);
    drawTensorBox(gs, xPos[1], rowY, '∂L/∂p', `[${seqLen}×${numClasses}]`, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, xPos[2], rowY, '∂L/∂y', `[${seqLen}×${numClasses}]`, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);

    arrowH(gs, xPos[0], xPos[1], rowY, COLORS.backward.stroke);
    arrowH(gs, xPos[1], xPos[2], rowY, COLORS.backward.stroke);

    lbl(gs, (xPos[0] + xPos[1]) / 2, rowY - 60, '∂L/∂p_i = p_i - 𝟙(i=tgt)',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });
    lbl(gs, (xPos[1] + xPos[2]) / 2, rowY - 60, '∂L/∂y = p - y_true (simplified)',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });

    shapeEq(gs, CX, rowY + 80,
      `chain rule: ∂L/∂y = (∂L/∂p) · (∂p/∂y), softmax+CE simplifies to p - y_true`,
      COLORS.backward.stroke);
    sampleNote(gs, CX, rowY + 80 + 38,
      `avoids computing full softmax Jacobian matrix`,
      COLORS.backward.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Outer', 'Outer Derivative — Loss & Softmax',
      '∂L/∂p = p - y_true, ∂L/∂y = p - y_true',
      'The outermost derivative computes how the loss changes with respect to softmax inputs. The combination of cross-entropy loss and softmax produces a clean gradient: predicted probability minus true label.',
      'step-outer', COLORS.backward.stroke, COLORS.backward.fill,
      [`dL_dp = p - F.one_hot(target, ${numClasses})`, `# simplified: dL_dy = p - y_true`]));
  }

  // Step 3: Middle Derivative
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-middle', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Middle Derivative — dL/dW2 & dL/da',
      '∂L/∂W2 = a^T·∂L/∂y, ∂L/∂a = ∂L/∂y·W2^T',
      COLORS.backward.fill, COLORS.backward.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xPos = [CX - 440, CX - 140, CX + 140, CX + 440];
    drawTensorBox(gs, xPos[0], rowY, '∂L/∂y', `[${seqLen}×${numClasses}]`, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, xPos[1], rowY, '∂L/∂W2', `[${dModel}×${numClasses}]`, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, xPos[2], rowY, 'a', `[${seqLen}×${dModel}]`, 160, 70,
      COLORS.forward.fill, COLORS.forward.stroke);
    drawTensorBox(gs, xPos[3], rowY, '∂L/∂a', `[${seqLen}×${dModel}]`, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);

    arrowH(gs, xPos[0], xPos[1], rowY, COLORS.backward.stroke);
    arrowH(gs, xPos[2], xPos[3], rowY, COLORS.backward.stroke);

    lbl(gs, (xPos[0] + xPos[1]) / 2, rowY - 60, '∂L/∂W2 = a^T · ∂L/∂y',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });
    lbl(gs, (xPos[2] + xPos[3]) / 2, rowY - 60, '∂L/∂a = ∂L/∂y · W2^T',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });

    lbl(gs, (xPos[0] + xPos[1]) / 2, rowY + 55, `a^T: [${dModel}×${seqLen}] · ∂L/∂y: [${seqLen}×${numClasses}]`,
      { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'middle' });
    lbl(gs, (xPos[2] + xPos[3]) / 2, rowY + 55, `∂L/∂y: [${seqLen}×${numClasses}] · W2^T: [${numClasses}×${dModel}]`,
      { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'middle' });

    shapeEq(gs, CX, rowY + 90,
      `y = a·W2: weight grad = input^T·output grad, input grad = output grad·W^T`,
      COLORS.backward.stroke);
    sampleNote(gs, CX, rowY + 90 + 38,
      `matrix chain rule: transpose left for weight grad, transpose right for input grad`,
      COLORS.backward.stroke);

    y = rowY + 90 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Middle', 'Middle Derivative — Layer 2',
      '∂L/∂W2 = a^T·∂L/∂y, ∂L/∂a = ∂L/∂y·W2^T',
      'For a linear layer y = a·W2, the chain rule gives two gradients: weight gradient (for updating W2) and input gradient (for backpropagating to earlier layers). Both involve matrix multiplication with transposes.',
      'step-middle', COLORS.backward.stroke, COLORS.backward.fill,
      [`dL_dW2 = a.T @ dL_dy`, `dL_da = dL_dy @ W2.T`, `# shapes: [${dModel}×${numClasses}], [${seqLen}×${dModel}]`]));
  }

  // Step 4: Inner Derivative
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-inner', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Inner Derivative — dL/dW1 & dL/dx',
      '∂L/∂h = (∂L/∂a)⊙σ\'(h), ∂L/∂W1 = x^T·∂L/∂h',
      COLORS.backward.fill, COLORS.backward.stroke);
    const row1Y = hBottom + BOX_TO_ROW;
    const row2Y = row1Y + 180;

    // Row 1: activation derivative chain
    const r1 = [
      { label: '∂L/∂a', sub: `[${seqLen}×${dModel}]`, x: CX - 380 },
      { label: 'σ\'(h)', sub: 'element-wise', x: CX - 80 },
      { label: '∂L/∂h', sub: `[${seqLen}×${dModel}]`, x: CX + 220 },
    ];

    drawTensorBox(gs, r1[0].x, row1Y, r1[0].label, r1[0].sub, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawOpNode(gs, r1[1].x, row1Y, r1[1].label, COLORS.backward.stroke, 36);
    drawTensorBox(gs, r1[2].x, row1Y, r1[2].label, r1[2].sub, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);

    lbl(gs, CX - 230, row1Y - 60, '∂L/∂h = ∂L/∂a ⊙ σ\'(h)',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });
    arrowH(gs, r1[0].x, r1[1].x - 36, row1Y, COLORS.backward.stroke);
    arrowH(gs, r1[1].x + 36, r1[2].x, row1Y, COLORS.backward.stroke);

    lbl(gs, CX - 80, row1Y + 55, '⊙ = element-wise product',
      { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'middle' });

    // Connecting arrow down
    arrowDown(gs, CX + 220, row1Y + 35, row2Y - 35, COLORS.backward.stroke);

    // Row 2: weight and input gradients
    const r2 = [
      { label: '∂L/∂h', sub: `[${seqLen}×${dModel}]`, x: CX - 380 },
      { label: '∂L/∂W1', sub: `[${dModel}×${dModel}]`, x: CX - 60 },
      { label: 'x', sub: `[${seqLen}×${dModel}]`, x: CX + 200 },
      { label: '∂L/∂x', sub: `[${seqLen}×${dModel}]`, x: CX + 460 },
    ];

    drawTensorBox(gs, r2[0].x, row2Y, r2[0].label, r2[0].sub, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, r2[1].x, row2Y, r2[1].label, r2[1].sub, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, r2[2].x, row2Y, r2[2].label, r2[2].sub, 160, 70,
      COLORS.weight.fill, COLORS.weight.stroke);
    drawTensorBox(gs, r2[3].x, row2Y, r2[3].label, r2[3].sub, 160, 70,
      COLORS.backward.fill, COLORS.backward.stroke);

    arrowH(gs, r2[0].x, r2[1].x, row2Y, COLORS.backward.stroke);
    arrowH(gs, r2[2].x, r2[3].x, row2Y, COLORS.backward.stroke);

    lbl(gs, (r2[0].x + r2[1].x) / 2, row2Y - 60, '∂L/∂W1 = x^T · ∂L/∂h',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });
    lbl(gs, (r2[2].x + r2[3].x) / 2, row2Y - 60, '∂L/∂x = ∂L/∂h · W1^T',
      { size: 11, color: COLORS.backward.stroke, font: 'monospace', anchor: 'middle' });

    shapeEq(gs, CX, row2Y + 80,
      `ReLU derivative: σ\'(h) = 1 if h>0 else 0, gates gradient flow`,
      COLORS.backward.stroke);
    sampleNote(gs, CX, row2Y + 80 + 38,
      `same pattern as layer 2: transpose left for weight, transpose right for input`,
      COLORS.backward.stroke);

    y = row2Y + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Inner', 'Inner Derivative — Layer 1',
      '∂L/∂h = ∂L/∂a⊙σ\'(h), ∂L/∂W1 = x^T·∂L/∂h',
      'The innermost derivative backpropagates through activation and the first linear layer. The element-wise product with σ\'(h) implements the activation derivative, which for ReLU simply gates the gradient.',
      'step-inner', COLORS.backward.stroke, COLORS.backward.fill,
      [`dL_dh = dL_da * (h > 0).float()`, `dL_dW1 = x.T @ dL_dh`, `dL_dx = dL_dh @ W1.T`]));
  }

  // Step 5: Summary
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-summary', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Summary — All Gradients',
      '∂L/∂W1, ∂L/∂W2 computed via chain rule decomposition',
      COLORS.update.fill, COLORS.update.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const formulas = [
      '∂L/∂W2 = a^T · (p - y_true)',
      '∂L/∂W1 = x^T · ((p - y_true)·W2^T ⊙ σ\'(h))',
      '∂L/∂x  = ((p - y_true)·W2^T ⊙ σ\'(h)) · W1^T',
    ];

    for (let i = 0; i < formulas.length; i++) {
      const fy = rowY + i * 48;
      gs.append('rect').attr('x', CX - 320).attr('y', fy - 18).attr('width', 640).attr('height', 36)
        .attr('rx', 4).attr('fill', '#fff').attr('stroke', COLORS.update.stroke).attr('stroke-width', 1.5);
      lbl(gs, CX, fy + 1, formulas[i], { size: 13, weight: '600', color: COLORS.update.stroke, font: 'monospace' });
    }

    shapeEq(gs, CX, rowY + 170,
      `chain rule decomposes ∂L/∂W into product of local derivatives`,
      COLORS.update.stroke);
    sampleNote(gs, CX, rowY + 170 + 38,
      `each parameter gradient = product of all derivatives on path from W to L`,
      COLORS.update.stroke);

    y = rowY + 170 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Summary', 'Summary — All Gradients',
      '∂L/∂W = ∏(local derivatives on path)',
      'The chain rule systematically decomposes the gradient of the loss with respect to each parameter into a product of local derivatives. Each parameter receives gradient information from all downstream operations.',
      'step-summary', COLORS.update.stroke, COLORS.update.fill,
      [`# Full backward pass`, `dL_dy = p - y_true`, `dL_dW2 = a.T @ dL_dy`, `dL_da = dL_dy @ W2.T`, `dL_dh = dL_da * (h > 0)`, `dL_dW1 = x.T @ dL_dh`]));
  }

  return { steps, y };
}

function renderMemoryAnalysis(
  g: Gsel, startY: number, seqLen: number, dModel: number, numClasses: number
): { steps: BackpropStep[]; y: number } {
  const steps: BackpropStep[] = [];
  let y = startY;

  const paramBytes = (dModel * dModel + dModel * numClasses) * 4;
  const actBytes = seqLen * dModel * 3 * 4 + seqLen * numClasses * 2 * 4;
  const gradBytes = paramBytes;
  const adamBytes = paramBytes * 2;
  const totalBytes = paramBytes + actBytes + gradBytes + adamBytes;

  // Step 1: Model Parameters
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-params', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Model Parameters',
      `W1: ${dModel}² = ${dModel * dModel}, W2: ${dModel}×${numClasses} = ${dModel * numClasses}`,
      COLORS.weight.fill, COLORS.weight.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xPos = [CX - 380, CX, CX + 380];
    drawTensorBox(gs, xPos[0], rowY, 'W1', `${dModel * dModel} params`, 180, 70,
      COLORS.weight.fill, COLORS.weight.stroke);
    drawTensorBox(gs, xPos[1], rowY, 'W2', `${dModel * numClasses} params`, 180, 70,
      COLORS.weight.fill, COLORS.weight.stroke);
    drawTensorBox(gs, xPos[2], rowY, 'Total', `${Math.round(paramBytes / 1024 / 1024 * 10) / 10} MB (FP32)`, 180, 70,
      COLORS.weight.fill, COLORS.weight.stroke);

    arrowH(gs, xPos[0], xPos[1], rowY, COLORS.weight.stroke);
    arrowH(gs, xPos[1], xPos[2], rowY, COLORS.weight.stroke);

    shapeEq(gs, CX, rowY + 80,
      `parameters: ${dModel}² + ${dModel}×${numClasses} = ${dModel * dModel + dModel * numClasses} × 4 bytes = ${(paramBytes / 1024 / 1024).toFixed(1)} MB`,
      COLORS.weight.stroke);
    sampleNote(gs, CX, rowY + 80 + 38,
      `FP32 precision: each parameter uses 4 bytes`,
      COLORS.weight.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Params', 'Model Parameters',
      'W1, W2 stored in GPU memory',
      'Model parameters are the learnable weights stored in GPU memory. Each parameter uses 4 bytes in FP32 precision. The total parameter memory scales with model size.',
      'step-params', COLORS.weight.stroke, COLORS.weight.fill,
      [`W1.shape = (${dModel}, ${dModel})  # ${dModel * dModel} params`, `W2.shape = (${dModel}, ${numClasses})  # ${dModel * numClasses} params`, `total_params = ${dModel * dModel + dModel * numClasses}`]));
  }

  // Step 2: Activation Memory
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-activations', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Forward Pass — Activation Memory',
      'each layer caches output for backward pass',
      COLORS.forward.fill, COLORS.forward.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const activations = [
      { label: 'x', size: `${seqLen}×${dModel}`, bytes: seqLen * dModel * 4, x: CX - 480 },
      { label: 'h', size: `${seqLen}×${dModel}`, bytes: seqLen * dModel * 4, x: CX - 240 },
      { label: 'a', size: `${seqLen}×${dModel}`, bytes: seqLen * dModel * 4, x: CX },
      { label: 'y', size: `${seqLen}×${numClasses}`, bytes: seqLen * numClasses * 4, x: CX + 240 },
      { label: 'p', size: `${seqLen}×${numClasses}`, bytes: seqLen * numClasses * 4, x: CX + 480 },
    ];

    for (const act of activations) {
      const kb = (act.bytes / 1024).toFixed(0);
      drawTensorBox(gs, act.x, rowY, act.label, `${act.size} = ${kb} KB`, 160, 70,
        COLORS.forward.fill, COLORS.forward.stroke);
    }

    shapeEq(gs, CX, rowY + 80,
      `activation memory: ${(actBytes / 1024 / 1024).toFixed(2)} MB cached for backward pass`,
      COLORS.forward.stroke);
    sampleNote(gs, CX, rowY + 80 + 38,
      `activations must be stored to compute gradients during backprop`,
      COLORS.forward.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Activations', 'Forward Pass — Activation Memory',
      'cache x, h, a, y, p for backward pass',
      'During the forward pass, all intermediate activations must be stored in memory. These cached values are essential for computing gradients during backpropagation. Activation memory scales with batch size and sequence length.',
      'step-activations', COLORS.forward.stroke, COLORS.forward.fill,
      [`# Cache activations during forward`, `cache = {'x': x, 'h': h, 'a': a, 'y': y, 'p': p}`, `# Required for backward pass gradient computation`]));
  }

  // Step 3: Gradient Memory
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-gradients', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Backward Pass — Gradient Memory',
      'gradients same size as parameters: ∂L/∂W1, ∂L/∂W2',
      COLORS.backward.fill, COLORS.backward.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xPos = [CX - 380, CX, CX + 380];
    drawTensorBox(gs, xPos[0], rowY, '∂L/∂W1', `${dModel}² = ${(dModel * dModel * 4 / 1024 / 1024).toFixed(1)} MB`, 180, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, xPos[1], rowY, '∂L/∂W2', `${dModel}×${numClasses} = ${(dModel * numClasses * 4 / 1024 / 1024).toFixed(1)} MB`, 180, 70,
      COLORS.backward.fill, COLORS.backward.stroke);
    drawTensorBox(gs, xPos[2], rowY, 'Total Grads', `${(gradBytes / 1024 / 1024).toFixed(1)} MB`, 180, 70,
      COLORS.backward.fill, COLORS.backward.stroke);

    arrowH(gs, xPos[0], xPos[1], rowY, COLORS.backward.stroke);
    arrowH(gs, xPos[1], xPos[2], rowY, COLORS.backward.stroke);

    shapeEq(gs, CX, rowY + 80,
      `gradient memory: ${(gradBytes / 1024 / 1024).toFixed(1)} MB = same as parameter memory`,
      COLORS.backward.stroke);
    sampleNote(gs, CX, rowY + 80 + 38,
      `each parameter needs a gradient tensor of identical size`,
      COLORS.backward.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Gradients', 'Backward Pass — Gradient Memory',
      '∂L/∂W1, ∂L/∂W2 stored for optimizer',
      'The backward pass computes gradients for all parameters. Each gradient tensor has the same size as its corresponding parameter. These gradients accumulate across mini-batches and are used by the optimizer.',
      'step-gradients', COLORS.backward.stroke, COLORS.backward.fill,
      [`W1.grad = dL_dW1  # shape (${dModel}, ${dModel})`, `W2.grad = dL_dW2  # shape (${dModel}, ${numClasses})`, `# Gradients accumulate over mini-batches`]));
  }

  // Step 4: Optimizer State Memory
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-optimizer', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Optimizer State Memory',
      'Adam: m (1st moment) + v (2nd moment), SGD: none',
      COLORS.memory.fill, COLORS.memory.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xPos = [CX - 440, CX - 140, CX + 140, CX + 440];
    drawTensorBox(gs, xPos[0], rowY, 'SGD', '0 extra states', 170, 70,
      '#e8f5e9', '#2e7d32');
    drawTensorBox(gs, xPos[1], rowY, 'SGD+Momentum', '1× param memory', 170, 70,
      '#fff3e0', '#e65100');
    drawTensorBox(gs, xPos[2], rowY, 'Adam m', '1st moment', 170, 70,
      COLORS.memory.fill, COLORS.memory.stroke);
    drawTensorBox(gs, xPos[3], rowY, 'Adam v', '2nd moment', 170, 70,
      COLORS.memory.fill, COLORS.memory.stroke);

    lbl(gs, CX, rowY + 60, `Adam total: 2× params = ${(adamBytes / 1024 / 1024).toFixed(1)} MB extra`,
      { size: 11, color: COLORS.memory.stroke, font: 'monospace', anchor: 'middle' });

    shapeEq(gs, CX, rowY + 100,
      `Adam: m = β₁·m + (1-β₁)·g, v = β₂·v + (1-β₂)·g²`,
      COLORS.memory.stroke);
    sampleNote(gs, CX, rowY + 100 + 38,
      `Adam doubles memory overhead vs SGD but converges faster`,
      COLORS.memory.stroke);

    y = rowY + 100 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Optimizer', 'Optimizer State Memory',
      'Adam stores m, v for each parameter',
      'Optimizers like Adam maintain additional state per parameter: first moment (momentum) and second moment (variance). This doubles the memory overhead compared to SGD, which stores no optimizer state.',
      'step-optimizer', COLORS.memory.stroke, COLORS.memory.fill,
      [`# Adam optimizer state`, `m = β₁ * m + (1 - β₁) * grad`, `v = β₂ * v + (1 - β₂) * grad**2`, `# m, v same size as params: ${(adamBytes / 1024 / 1024).toFixed(1)} MB`]));
  }

  // Step 5: Total Memory + Gradient Checkpointing
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-total', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Total Memory + Gradient Checkpointing',
      `total: ${(totalBytes / 1024 / 1024).toFixed(1)} MB, checkpointing saves activation memory`,
      COLORS.update.fill, COLORS.update.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const breakdown = [
      { label: 'Parameters', bytes: paramBytes, color: COLORS.weight.stroke },
      { label: 'Gradients', bytes: gradBytes, color: COLORS.backward.stroke },
      { label: 'Adam States', bytes: adamBytes, color: COLORS.memory.stroke },
      { label: 'Activations', bytes: actBytes, color: COLORS.forward.stroke },
    ];

    const barX = CX - 380;
    const barW = 760;
    const barH = 50;
    let cumX = barX;

    for (const item of breakdown) {
      const w = Math.max(60, (item.bytes / totalBytes) * barW);
      gs.append('rect').attr('x', cumX).attr('y', rowY - barH / 2).attr('width', w).attr('height', barH)
        .attr('fill', item.color).attr('opacity', 0.25).attr('stroke', item.color).attr('stroke-width', 2);
      lbl(gs, cumX + w / 2, rowY - 2, `${item.label}`, { size: 10, weight: '600', color: item.color, font: 'monospace' });
      lbl(gs, cumX + w / 2, rowY + 14, `${(item.bytes / 1024 / 1024).toFixed(1)} MB`, { size: 9, color: item.color, font: 'monospace' });
      cumX += w;
    }

    lbl(gs, CX, rowY + 50, `Total: ${(totalBytes / 1024 / 1024).toFixed(1)} MB`,
      { size: 13, weight: '700', color: COLORS.update.stroke, anchor: 'middle' });

    const cpX = [CX - 240, CX + 240];
    drawTensorBox(gs, cpX[0], rowY + 140, 'Without Checkpoint', `full activation cache`, 200, 70,
      '#ffebee', '#d32f2f');
    drawTensorBox(gs, cpX[1], rowY + 140, 'With Checkpoint', `recompute activations`, 200, 70,
      '#e8f5e9', '#2e7d32');

    lbl(gs, CX, rowY + 140 + 55, `saves ${(actBytes / 1024 / 1024).toFixed(2)} MB, costs ~33% more compute`,
      { size: 11, color: COLORS.update.stroke, font: 'monospace', anchor: 'middle' });

    shapeEq(gs, CX, rowY + 240,
      `gradient checkpointing: trade compute for memory by recomputing activations`,
      COLORS.update.stroke);
    sampleNote(gs, CX, rowY + 240 + 38,
      `recompute activations during backward instead of storing them`,
      COLORS.update.stroke);

    y = rowY + 240 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Total', 'Total Memory + Gradient Checkpointing',
      'params + grads + optimizer + activations',
      'Total training memory includes parameters, gradients, optimizer states, and cached activations. Gradient checkpointing reduces activation memory by recomputing values during backprop, trading ~33% more compute for significant memory savings.',
      'step-total', COLORS.update.stroke, COLORS.update.fill,
      [`# Total memory breakdown`, `params: ${(paramBytes / 1024 / 1024).toFixed(1)} MB`, `grads: ${(gradBytes / 1024 / 1024).toFixed(1)} MB`, `adam: ${(adamBytes / 1024 / 1024).toFixed(1)} MB`, `acts: ${(actBytes / 1024 / 1024).toFixed(2)} MB`, `total: ${(totalBytes / 1024 / 1024).toFixed(1)} MB`]));
  }

  return { steps, y };
}

export function renderBackpropagationDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const seqLen = Number(params.seq_len) || 128;
  const dModel = Number(params.d_model) || 512;
  const numClasses = Number(params.num_classes) || 1000;
  const variant = String(params.variant || 'computation_graph') as BackpropVariant;

  const stepsMeta: BackpropStep[] = [];
  let y = 10;

  lbl(g, CX, y + 14, 'Backpropagation', { size: 18, weight: '700', color: 'var(--text)' });
  lbl(g, CX, y + 36, 'Chain-rule gradient flow through computation graph', { size: 11, color: COLORS.muted });
  y += 56;

  const { steps, y: finalY } = variant === 'chain_rule'
    ? renderChainRule(g, y, seqLen, dModel, numClasses)
    : variant === 'memory_analysis'
      ? renderMemoryAnalysis(g, y, seqLen, dModel, numClasses)
      : renderComputationGraph(g, y, seqLen, dModel, numClasses);
  stepsMeta.push(...steps);
  y = finalY;

  const insightText = variant === 'chain_rule'
    ? 'Backpropagation decomposes the gradient of the loss with respect to each weight using the chain rule. Each parameter receives a gradient that is the product of all local derivatives on the path from that parameter to the loss.'
    : variant === 'memory_analysis'
      ? 'Memory cost: all intermediate activations must be stored for the backward pass. Gradient checkpointing trades compute for memory by recomputing activations. Adam optimizer doubles memory overhead compared to SGD.'
      : 'Backpropagation computes gradients by applying the chain rule in reverse order through the computation graph. The forward pass caches activations; the backward pass uses them to compute parameter gradients efficiently.';

  const paramBytes = (dModel * dModel + dModel * numClasses) * 4;
  const actBytes = seqLen * dModel * 3 * 4 + seqLen * numClasses * 2 * 4;
  const gradBytes = paramBytes;
  const adamBytes = paramBytes * 2;
  const totalBytes = paramBytes + actBytes + gradBytes + adamBytes;

  const perfText = variant === 'memory_analysis'
    ? `Training memory: parameters (${(paramBytes / 1024 / 1024).toFixed(1)} MB) + gradients (${(gradBytes / 1024 / 1024).toFixed(1)} MB) + Adam states (${(adamBytes / 1024 / 1024).toFixed(1)} MB) + activations (${(actBytes / 1024 / 1024).toFixed(2)} MB) = ${(totalBytes / 1024 / 1024).toFixed(1)} MB total.`
    : 'Backward pass is O(batch_size × seq_len × d_model²) for each linear layer. Memory scales with batch size and sequence length due to activation caching.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'matmul', 'Matmul');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'cross-entropy', 'Cross Entropy');
  y += 80;

  const codeLines = variant === 'chain_rule'
    ? ['# Chain rule decomposition', 'dL_dy = p - y_true', 'dL_dW2 = a.T @ dL_dy', 'dL_da = dL_dy @ W2.T', 'dL_dh = dL_da * (h > 0)', 'dL_dW1 = x.T @ dL_dh']
    : variant === 'memory_analysis'
      ? ['# Memory tracking', 'param_mem = sum(p.numel() for p in params) * 4', 'act_mem = sum(a.numel() for a in cache) * 4', 'grad_mem = param_mem', 'adam_mem = 2 * param_mem', 'total = param_mem + act_mem + grad_mem + adam_mem']
      : ['# Forward pass', 'h = x @ W1', 'a = F.relu(h)', 'y = a @ W2', 'loss = F.cross_entropy(y, targets)', '', '# Backward pass (autograd)', 'loss.backward()', '', '# SGD update', 'W1.data -= lr * W1.grad', 'W2.data -= lr * W2.grad'];

  y = drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160,
    'Backpropagation (PyTorch)', [`variant: ${variant.replace('_', ' ')}`], codeLines);

  return { width: W, height: y + FOOTER_PAD, steps: stepsMeta };
}
